PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE IF NOT EXISTS "content_changelog_entry" ("id" TEXT PRIMARY KEY, "_status" TEXT NOT NULL DEFAULT 'draft', "_published_at" TEXT, "_first_published_at" TEXT, "_published_snapshot" TEXT, "_created_at" TEXT NOT NULL, "_updated_at" TEXT NOT NULL, "_created_by" TEXT, "_updated_by" TEXT, "_published_by" TEXT, "_scheduled_publish_at" TEXT, "_scheduled_unpublish_at" TEXT, "_position" INTEGER NOT NULL DEFAULT 0, "date" TEXT, "title" TEXT, "description" TEXT, "change_type" TEXT, "guide" TEXT);
